const verificationKeyReferences = `-- name: VerificationKeyReferences :many
SELECT DISTINCT verification_key_id FROM platform_mail_producer_outbox
WHERE namespace=$1 AND producer_id=$2 AND template='email_verification' AND state IN ('queued','claimed') AND expires_at>clock_timestamp()
`

type VerificationKeyReferencesParams struct {
	Namespace  string
	ProducerID string
}

func (q *Queries) VerificationKeyReferences(ctx context.Context, db DBTX, arg VerificationKeyReferencesParams) ([]string, error) {
	rows, err := db.Query(ctx, verificationKeyReferences, arg.Namespace, arg.ProducerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var verification_key_id string
		if err := rows.Scan(&verification_key_id); err != nil {
			return nil, err
		}
		items = append(items, verification_key_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
